#include "cryptoutils.h"
typedef struct { double score; char text[4096]; } Candidate;
static const char *trigrams[]={"THE","AND","ING","HER","ERE","ENT","THA","NTH","WAS","ETH","FOR","DTH","HAT","ION","TIO","VER","TER","HES","ATE","ALL","ITH","HIS","OFT","STH","EST","ERS","ATI","REA","NOT","YOU"};
static double score_text(const char *s){double sc=0;size_t n=strlen(s);for(size_t i=0;i<n;i++){if(isalpha((unsigned char)s[i])){if(i+2<n){char t[4]={(char)toupper((unsigned char)s[i]),(char)toupper((unsigned char)s[i+1]),(char)toupper((unsigned char)s[i+2]),0};for(size_t k=0;k<sizeof(trigrams)/sizeof(trigrams[0]);k++)if(strcmp(t,trigrams[k])==0)sc+=4.0;}if(i+1<n){char a=(char)toupper((unsigned char)s[i]),b=(char)toupper((unsigned char)s[i+1]);if((a=='T'&&b=='H')||(a=='H'&&b=='E')||(a=='I'&&b=='N')||(a=='E'&&b=='R')||(a=='A'&&b=='N')||(a=='R'&&b=='E')||(a=='O'&&b=='N'))sc+=0.8;}}else if(s[i]==' ')sc+=0.1;}return sc;}
int main(void){char ct[4096];cu_readline("Ciphertext (single substitution): ",ct,sizeof ct);int cnt[26]={0},order[26];for(size_t i=0;ct[i];i++)if(isalpha((unsigned char)ct[i]))cnt[toupper((unsigned char)ct[i])-'A']++;for(int i=0;i<26;i++)order[i]=i;for(int i=0;i<26;i++)for(int j=i+1;j<26;j++)if(cnt[order[j]]>cnt[order[i]]){int t=order[i];order[i]=order[j];order[j]=t;}const char *english="ETAOINSHRDLCUMWFGYPBVKJXQZ";char map[26];for(int r=0;r<26;r++)map[order[r]]=english[r];Candidate best[10];for(int i=0;i<10;i++){best[i].score=-1e99;best[i].text[0]=0;}unsigned seed=1234567;for(int attempt=0;attempt<5000;attempt++){char m[26];memcpy(m,map,26);int swaps=attempt%5;for(int z=0;z<swaps;z++){seed=seed*1103515245u+12345u;int a=(seed>>16)%26;seed=seed*1103515245u+12345u;int b=(seed>>16)%26;char t=m[a];m[a]=m[b];m[b]=t;}char out[4096];size_t j=0;for(size_t i=0;ct[i]&&j+1<sizeof out;i++){unsigned char c=(unsigned char)ct[i];if(isupper(c))out[j++]=m[c-'A'];else if(islower(c))out[j++]=(char)tolower((unsigned char)m[c-'a']);else out[j++]=(char)c;}out[j]=0;double sc=score_text(out);int dup=0;for(int k=0;k<10;k++)if(strcmp(best[k].text,out)==0)dup=1;if(dup)continue;for(int k=0;k<10;k++)if(sc>best[k].score){for(int z=9;z>k;z--)best[z]=best[z-1];best[k].score=sc;snprintf(best[k].text,sizeof best[k].text,"%s",out);break;}}puts("Top heuristic candidates (ranked by common English trigrams/bigrams; verify manually):");for(int i=0;i<10&&best[i].score>-1e90;i++)printf("%2d [%.1f] %s\n",i+1,best[i].score,best[i].text);puts("A full substitution cipher is hard to solve reliably without a larger language model/dictionary; these candidates are guesses, not guaranteed plaintext.");return 0;}
